export function getProductsByCategory(slug: string): Product[] {
    return products.filter((p) => p.categorySlug === slug);
}

export function getProductsByIndustry(slug: string): Product[] {
    return products.filter((p) => p.industries.some((i) => i.slug === slug));
}

export function getProductBySlug(slug: string): Product | undefined {
    return products.find((p) => p.slug === slug);
}

/** Related products: same type first, then same category. */
export function getRelatedProducts(p: Product, limit = 6): Product[] {
    const sameType = products.filter((x) => x.slug !== p.slug && x.categorySlug === p.categorySlug && x.type === p.type);
    const sameCat = products.filter((x) => x.slug !== p.slug && x.categorySlug === p.categorySlug && x.type !== p.type);
    return [...sameType, ...sameCat].slice(0, limit);
}

